const clamp = (n, low, high) => Math.max(low, Math.min(high, n));

// Numerical Recipes LCG: uint32 arithmetic is reproducible across JS engines.
function random(state) {
  state.rng = (Math.imul(state.rng, 1664525) + 1013904223) >>> 0;
  return state.rng / 4294967296;
}

export function burst(state, x, y, kind, count) {
  for (let i = 0; i < count; i++) {
    const angle = random(state) * Math.PI * 2;
    const speed = 35 + random(state) * 130;
    state.particles.push({ x, y, vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed,
      life: 0.25 + random(state) * 0.4, kind });
  }
  if (state.particles.length > 120) state.particles.splice(0, state.particles.length - 120);
}

export function spawnFly(state) {
  if (state.flies.length >= 14) return;
  let x = 640, y = 360;
  for (let attempt = 0; attempt < 12; attempt++) {
    x = 60 + random(state) * 1160;
    y = 70 + random(state) * 580;
    if (Math.hypot(x - state.player.x, y - state.player.y) > 110 &&
        state.flies.every(fly => Math.hypot(x - fly.x, y - fly.y) > 55)) break;
  }
  state.flies.push({ id: `fly-${state.rng}-${Math.round(state.time * 1000)}`, x, y, radius: 9 });
}

function intersects(p, hazard) {
  const x = clamp(p.x, hazard.x, hazard.x + hazard.w);
  const y = clamp(p.y, hazard.y, hazard.y + hazard.h);
  return (x - p.x) ** 2 + (y - p.y) ** 2 <= p.radius ** 2;
}

function warn(state, index) {
  // One warning/active attack at a time leaves a guaranteed open escape route.
  if (state.hazards.some(h => h.phase !== 'fade') || state.hazards.length >= 4) return;
  const difficulty = Math.min(9, state.wave - 1);
  const kind = ['slap', 'glass', 'sweep'][(index + state.wave - 1) % 3];
  const p = state.player;
  let w, h, x, y;
  if (kind === 'sweep') {
    const vertical = random(state) < 0.5;
    w = vertical ? 170 + difficulty * 5 : 1280;
    h = vertical ? 720 : 130 + difficulty * 4;
    x = vertical ? clamp(p.x - w / 2, 0, 1280 - w) : 0;
    y = vertical ? 0 : clamp(p.y - h / 2, 0, 720 - h);
  } else {
    w = (kind === 'glass' ? 190 : 235) + difficulty * 7;
    h = (kind === 'glass' ? 190 : 155) + difficulty * 5;
    x = clamp(p.x - w / 2 + (random(state) - 0.5) * 50, 12, 1268 - w);
    y = clamp(p.y - h / 2 + (random(state) - 0.5) * 40, 12, 708 - h);
  }
  state.hazards.push({ id: `attack-${state.wave}-${index}`, kind, phase: 'warning',
    x, y, w, h, remaining: 1.45 - difficulty * 0.045 });
}

export function updateHazards(state, dt) {
  const p = state.player;
  const wave = Math.floor(state.time / 18) + 1;
  if (wave !== state.wave) {
    state.wave = wave;
    state.events.push({ type: 'wave', x: 640, y: 100 });
  }
  for (const hazard of state.hazards) {
    hazard.remaining -= dt;
    if (hazard.remaining <= 0) {
      if (hazard.phase === 'warning') {
        hazard.phase = 'active';
        hazard.remaining = hazard.kind === 'slap' ? 0.24 : hazard.kind === 'glass' ? 1.05 : 0.6;
        state.events.push({ type: 'attack', x: hazard.x + hazard.w / 2, y: hazard.y + hazard.h / 2 });
      } else if (hazard.phase === 'active') {
        hazard.phase = 'fade';
        hazard.remaining = 0.32;
        if (p.invulnerable <= 0) { state.stats.dodges++; state.score += 25; }
      }
    }
    if (hazard.phase === 'active' && p.invulnerable <= 0 && intersects(p, hazard)) {
      p.hp = Math.max(0, p.hp - 1);
      p.invulnerable = 1.65;
      state.score = Math.max(0, state.score - 10);
      state.events.push({ type: 'hurt', x: p.x, y: p.y });
      burst(state, p.x, p.y, 'hit', 14);
    }
  }
  state.hazards = state.hazards.filter(h => h.phase !== 'fade' || h.remaining > 0).slice(-4);
  // Every wave has a short breath; increasing frequency never overlaps live attacks.
  const interval = Math.max(2.85, 4.8 - (wave - 1) * 0.21);
  const local = state.time - (wave - 1) * 18;
  const previous = Math.max(0, local - dt);
  const index = Math.floor((local - 2) / interval);
  if (local >= 2 && (previous < 2 || Math.floor((previous - 2) / interval) < index)) warn(state, index);
}

