// Lazy, gesture-unlocked Web Audio. No media, timers, or browser globals at import time.
const VOICES = {
  web: [[680, 290, 0, .12, 'sine', .09]],
  dash: [[190, 760, 0, .13, 'triangle', .10]],
  catch: [[880, 1100, 0, .09, 'sine', .10], [1320, 1540, .07, .16, 'sine', .07]],
  hurt: [[135, 48, 0, .23, 'sawtooth', .08], [72, 38, .03, .24, 'sine', .16]],
  attack: [[90, 32, 0, .24, 'triangle', .17]],
  wave: [[220, 220, 0, .22, 'sine', .08], [277, 277, .16, .26, 'sine', .07]],
  win: [[440, 440, 0, .22, 'triangle', .08], [554, 554, .15, .22, 'triangle', .08], [659, 880, .30, .55, 'sine', .10]],
  lose: [[220, 196, 0, .35, 'triangle', .08], [165, 82, .23, .65, 'sine', .10]],
};

export function createAudio() {
  let context = null, master = null, muted = false, disposed = false;
  const active = new Set();
  const last = new Map();

  function unlock() {
    if (disposed) return Promise.resolve(false);
    try {
      if (!context) {
        const Audio = globalThis.AudioContext || globalThis.webkitAudioContext;
        if (!Audio) return Promise.resolve(false);
        context = new Audio();
        master = context.createGain();
        master.gain.value = muted ? 0 : .38;
        master.connect(context.destination);
      }
      return Promise.resolve(context.state === 'suspended' ? context.resume() : undefined)
        .then(() => context?.state === 'running').catch(() => false);
    } catch { return Promise.resolve(false); }
  }

  function play(type) {
    if (disposed || muted || !context || context.state !== 'running' || !VOICES[type]) return;
    const now = context.currentTime;
    // Bound dense catch/web bursts without discarding distinct events.
    if (now - (last.get(type) ?? -10) < .045 || active.size > 24) return;
    last.set(type, now);
    try {
      for (const [start, end, delay, duration, shape, volume] of VOICES[type]) {
        const oscillator = context.createOscillator(), envelope = context.createGain();
        const t = now + delay;
        oscillator.type = shape;
        oscillator.frequency.setValueAtTime(start, t);
        oscillator.frequency.exponentialRampToValueAtTime(end, t + duration);
        envelope.gain.setValueAtTime(.0001, t);
        envelope.gain.exponentialRampToValueAtTime(volume, t + .009);
        envelope.gain.exponentialRampToValueAtTime(.0001, t + duration);
        oscillator.connect(envelope); envelope.connect(master); active.add(oscillator);
        oscillator.onended = () => { active.delete(oscillator); oscillator.disconnect(); envelope.disconnect(); };
        oscillator.start(t); oscillator.stop(t + duration + .03);
      }
    } catch { /* Audio may be interrupted or revoked by the browser. Gameplay continues. */ }
  }

  function setMuted(value) {
    muted = Boolean(value);
    if (!master || !context || disposed) return;
    try {
      master.gain.cancelScheduledValues(context.currentTime);
      master.gain.setTargetAtTime(muted ? 0 : .38, context.currentTime, .015);
    } catch { /* Closed audio device. */ }
  }

  function dispose() {
    if (disposed) return;
    disposed = true;
    for (const oscillator of active) { try { oscillator.stop(); oscillator.disconnect(); } catch { /* Already ended. */ } }
    active.clear(); last.clear();
    try { master?.disconnect(); Promise.resolve(context?.close()).catch(() => {}); } catch { /* Already closed. */ }
    master = null; context = null;
  }
  return { unlock, play, setMuted, dispose };
}
